-- =============================================================================
-- Personal Productivity Dashboard: schema, integrity triggers, and RLS.
--
-- Conventions shared by every synced table:
--   id          uuid primary key, generated by the client (stable across retries)
--   user_id     owner; always forced to auth.uid() for API callers
--   version     integer bumped by trigger on every update (optimistic concurrency)
--   created_at  set on insert, immutable afterwards
--   updated_at  set by trigger on every write (drives incremental pull)
--   deleted_at  tombstone; rows are soft-deleted so deletions can be synchronized
--
-- Child tables use composite foreign keys (user_id, parent_id) so a row can never
-- reference a parent that belongs to a different user.
-- =============================================================================

create table public.groups (
  id           uuid primary key,
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name         text not null check (char_length(name) between 1 and 120),
  description  text not null default '' check (char_length(description) <= 2000),
  color        text not null default '#6366f1' check (color ~ '^#[0-9a-fA-F]{6}$'),
  icon         text not null default '📁' check (char_length(icon) between 1 and 16),
  -- Group order (Move Up / Move Down, drag in auto-arrange mode).
  sort_index   double precision not null default 0,
  collapsed    boolean not null default false,
  -- Dashboard position (free-placement mode). NULL = never placed manually.
  grid_x       integer check (grid_x between 0 and 11),
  grid_y       integer check (grid_y between 0 and 100000),
  -- Card dimensions, in grid units (12 columns wide).
  grid_w       integer not null default 4 check (grid_w between 3 and 12),
  grid_h       integer not null default 8 check (grid_h between 4 and 30),
  -- Task sort preference for this group. 'manual' uses tasks.manual_index.
  sort_field   text not null default 'due' check (sort_field in ('manual', 'title', 'due', 'label', 'priority')),
  sort_dir     text not null default 'asc' check (sort_dir in ('asc', 'desc')),
  version      integer not null default 1,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (user_id, id)
);

create table public.labels (
  id           uuid primary key,
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name         text not null check (char_length(name) between 1 and 60),
  color        text not null default '#64748b' check (color ~ '^#[0-9a-fA-F]{6}$'),
  version      integer not null default 1,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (user_id, id)
);

-- A recurrence series holds the rule and the template used to create the next
-- occurrence. Occurrences themselves are ordinary rows in public.tasks, so the
-- completion history of a series is simply its completed task rows.
create table public.recurrence_series (
  id             uuid primary key,
  user_id        uuid not null default auth.uid() references auth.users (id) on delete cascade,
  group_id       uuid not null,
  unit           text not null check (unit in ('day', 'week', 'month')),
  interval_count integer not null default 1 check (interval_count between 1 and 365),
  -- Occurrence k falls on anchor_date + k * interval_count units. Monthly dates
  -- are always derived from the anchor so "the 31st" is never lost.
  anchor_date    date not null,
  title          text not null check (char_length(title) between 1 and 300),
  description    text not null default '' check (char_length(description) <= 50000),
  priority       text not null default 'medium' check (priority in ('low', 'medium', 'high', 'urgent')),
  due_time       time,
  label_ids      jsonb not null default '[]'::jsonb check (jsonb_typeof(label_ids) = 'array'),
  subtasks       jsonb not null default '[]'::jsonb check (jsonb_typeof(subtasks) = 'array'),
  ended_at       timestamptz,
  version        integer not null default 1,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  deleted_at     timestamptz,
  unique (user_id, id),
  foreign key (user_id, group_id) references public.groups (user_id, id) on delete cascade
);

create table public.tasks (
  id              uuid primary key,
  user_id         uuid not null default auth.uid() references auth.users (id) on delete cascade,
  group_id        uuid not null,
  title           text not null check (char_length(title) between 1 and 300),
  -- Sanitized HTML (bold, italic, lists, links). Sanitized again on render.
  description     text not null default '' check (char_length(description) <= 50000),
  priority        text not null default 'medium' check (priority in ('low', 'medium', 'high', 'urgent')),
  -- Deadlines are "floating" local values: a calendar date plus an optional
  -- wall-clock time, interpreted in the viewer's time zone. A date-only
  -- deadline has due_time NULL and is never given an arbitrary time of day.
  due_date        date,
  due_time        time,
  completed_at    timestamptz,
  -- Manual order within the group; untouched by automatic sorting.
  manual_index    double precision not null default 0,
  series_id       uuid,
  -- The date the recurrence rule scheduled this occurrence for (may differ from
  -- due_date when a single occurrence was rescheduled).
  occurrence_date date,
  version         integer not null default 1,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  deleted_at      timestamptz,
  unique (user_id, id),
  check (due_time is null or due_date is not null),
  check ((series_id is null) = (occurrence_date is null)),
  foreign key (user_id, group_id) references public.groups (user_id, id) on delete cascade,
  foreign key (user_id, series_id) references public.recurrence_series (user_id, id)
);

create table public.subtasks (
  id           uuid primary key,
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  task_id      uuid not null,
  text         text not null check (char_length(text) between 1 and 500),
  completed    boolean not null default false,
  sort_index   double precision not null default 0,
  version      integer not null default 1,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  foreign key (user_id, task_id) references public.tasks (user_id, id) on delete cascade
);

create table public.task_labels (
  id           uuid primary key,
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  task_id      uuid not null,
  label_id     uuid not null,
  version      integer not null default 1,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (task_id, label_id),
  foreign key (user_id, task_id) references public.tasks (user_id, id) on delete cascade,
  foreign key (user_id, label_id) references public.labels (user_id, id) on delete cascade
);

-- One row per setting key so each preference (theme, widget order, priority
-- colors, layout mode, ...) is versioned and synchronized independently.
create table public.user_settings (
  id           uuid primary key,
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  key          text not null check (key ~ '^[a-z][a-z0-9_]{0,39}$'),
  value        jsonb,
  version      integer not null default 1,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (user_id, key),
  check (value is null or octet_length(value::text) <= 20000)
);

-- Idempotency ledger: every successfully applied client mutation is recorded so
-- a retried request can never be applied twice.
create table public.applied_mutations (
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  mutation_id  uuid not null,
  applied_at   timestamptz not null default now(),
  primary key (user_id, mutation_id)
);

-- ----------------------------------------------------------------------------
-- Indexes
-- ----------------------------------------------------------------------------
create index groups_pull_idx            on public.groups (user_id, updated_at);
create index labels_pull_idx            on public.labels (user_id, updated_at);
create index recurrence_series_pull_idx on public.recurrence_series (user_id, updated_at);
create index recurrence_series_group_idx on public.recurrence_series (user_id, group_id);
create index tasks_pull_idx             on public.tasks (user_id, updated_at);
create index tasks_group_idx            on public.tasks (user_id, group_id);
create index tasks_series_idx           on public.tasks (user_id, series_id) where series_id is not null;
create index tasks_due_idx              on public.tasks (user_id, due_date) where deleted_at is null and completed_at is null;
create index subtasks_pull_idx          on public.subtasks (user_id, updated_at);
create index subtasks_task_idx          on public.subtasks (user_id, task_id);
create index task_labels_pull_idx       on public.task_labels (user_id, updated_at);
create index task_labels_task_idx       on public.task_labels (user_id, task_id);
create index task_labels_label_idx      on public.task_labels (user_id, label_id);
create index user_settings_pull_idx     on public.user_settings (user_id, updated_at);
create index applied_mutations_age_idx  on public.applied_mutations (user_id, applied_at);

-- ----------------------------------------------------------------------------
-- Row bookkeeping triggers
-- ----------------------------------------------------------------------------

-- Insert: force ownership to the caller and initialise server-managed columns.
create function public.tg_row_insert() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
begin
  if auth.uid() is not null then
    new.user_id := auth.uid();
  end if;
  new.version := 1;
  new.created_at := coalesce(new.created_at, now());
  new.updated_at := clock_timestamp();
  return new;
end;
$$;

-- Update: ownership and identity are immutable (plus any columns named in the
-- trigger arguments, e.g. tasks.group_id); version and updated_at always advance.
create function public.tg_row_update() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  col text;
begin
  if new.id is distinct from old.id then
    raise exception 'id is immutable' using errcode = '42501';
  end if;
  if new.user_id is distinct from old.user_id then
    raise exception 'user_id is immutable' using errcode = '42501';
  end if;
  if tg_nargs > 0 then
    foreach col in array tg_argv loop
      if (to_jsonb(new) -> col) is distinct from (to_jsonb(old) -> col) then
        raise exception '%.% is immutable', tg_table_name, col using errcode = '42501';
      end if;
    end loop;
  end if;
  new.created_at := old.created_at;
  new.version := old.version + 1;
  new.updated_at := clock_timestamp();
  return new;
end;
$$;

create trigger groups_ins            before insert on public.groups            for each row execute function public.tg_row_insert();
create trigger labels_ins            before insert on public.labels            for each row execute function public.tg_row_insert();
create trigger recurrence_series_ins before insert on public.recurrence_series for each row execute function public.tg_row_insert();
create trigger tasks_ins             before insert on public.tasks             for each row execute function public.tg_row_insert();
create trigger subtasks_ins          before insert on public.subtasks          for each row execute function public.tg_row_insert();
create trigger task_labels_ins       before insert on public.task_labels       for each row execute function public.tg_row_insert();
create trigger user_settings_ins     before insert on public.user_settings     for each row execute function public.tg_row_insert();

create trigger groups_upd            before update on public.groups            for each row execute function public.tg_row_update();
create trigger labels_upd            before update on public.labels            for each row execute function public.tg_row_update();
create trigger recurrence_series_upd before update on public.recurrence_series for each row execute function public.tg_row_update('group_id');
-- Tasks can never be moved between groups.
create trigger tasks_upd             before update on public.tasks             for each row execute function public.tg_row_update('group_id');
create trigger subtasks_upd          before update on public.subtasks          for each row execute function public.tg_row_update('task_id');
create trigger task_labels_upd       before update on public.task_labels       for each row execute function public.tg_row_update('task_id', 'label_id');
create trigger user_settings_upd     before update on public.user_settings     for each row execute function public.tg_row_update('key');

create function public.tg_applied_mutation_insert() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
begin
  if auth.uid() is not null then
    new.user_id := auth.uid();
  end if;
  new.applied_at := now();
  return new;
end;
$$;
create trigger applied_mutations_ins before insert on public.applied_mutations for each row execute function public.tg_applied_mutation_insert();

-- ----------------------------------------------------------------------------
-- Tombstone cascades
--
-- Soft-deleting a parent soft-deletes its children with the *same* deleted_at
-- timestamp. Restoring the parent (deleted_at -> NULL) restores exactly the
-- children that were removed by that cascade, and nothing deleted earlier.
-- ----------------------------------------------------------------------------
create function public.tg_group_tombstone() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
begin
  if old.deleted_at is null and new.deleted_at is not null then
    update public.tasks set deleted_at = new.deleted_at
      where user_id = new.user_id and group_id = new.id and deleted_at is null;
    update public.recurrence_series set deleted_at = new.deleted_at
      where user_id = new.user_id and group_id = new.id and deleted_at is null;
  elsif old.deleted_at is not null and new.deleted_at is null then
    update public.recurrence_series set deleted_at = null
      where user_id = new.user_id and group_id = new.id and deleted_at = old.deleted_at;
    update public.tasks set deleted_at = null
      where user_id = new.user_id and group_id = new.id and deleted_at = old.deleted_at;
  end if;
  return null;
end;
$$;

create function public.tg_task_tombstone() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
begin
  if old.deleted_at is null and new.deleted_at is not null then
    update public.subtasks set deleted_at = new.deleted_at
      where user_id = new.user_id and task_id = new.id and deleted_at is null;
    update public.task_labels set deleted_at = new.deleted_at
      where user_id = new.user_id and task_id = new.id and deleted_at is null;
  elsif old.deleted_at is not null and new.deleted_at is null then
    update public.subtasks set deleted_at = null
      where user_id = new.user_id and task_id = new.id and deleted_at = old.deleted_at;
    update public.task_labels tl set deleted_at = null
      where tl.user_id = new.user_id and tl.task_id = new.id and tl.deleted_at = old.deleted_at
        and exists (select 1 from public.labels l where l.id = tl.label_id and l.deleted_at is null);
  end if;
  return null;
end;
$$;

create function public.tg_label_tombstone() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
begin
  if old.deleted_at is null and new.deleted_at is not null then
    update public.task_labels set deleted_at = new.deleted_at
      where user_id = new.user_id and label_id = new.id and deleted_at is null;
  elsif old.deleted_at is not null and new.deleted_at is null then
    update public.task_labels tl set deleted_at = null
      where tl.user_id = new.user_id and tl.label_id = new.id and tl.deleted_at = old.deleted_at
        and exists (select 1 from public.tasks t where t.id = tl.task_id and t.deleted_at is null);
  end if;
  return null;
end;
$$;

create trigger groups_tombstone after update of deleted_at on public.groups for each row execute function public.tg_group_tombstone();
create trigger tasks_tombstone  after update of deleted_at on public.tasks  for each row execute function public.tg_task_tombstone();
create trigger labels_tombstone after update of deleted_at on public.labels for each row execute function public.tg_label_tombstone();

-- A child inserted under an already-deleted parent (for example: created
-- offline while another device deleted the group) is born deleted, so it can
-- never become an orphan that is visible without its parent.
create function public.tg_child_insert() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
declare
  parent_deleted timestamptz;
begin
  if tg_table_name in ('tasks', 'recurrence_series') then
    select g.deleted_at into parent_deleted from public.groups g where g.id = new.group_id;
  elsif tg_table_name = 'subtasks' then
    select t.deleted_at into parent_deleted from public.tasks t where t.id = new.task_id;
  elsif tg_table_name = 'task_labels' then
    select max(d) into parent_deleted from (
      select t.deleted_at as d from public.tasks t where t.id = new.task_id
      union all
      select l.deleted_at as d from public.labels l where l.id = new.label_id
    ) parents;
  end if;
  if parent_deleted is not null and new.deleted_at is null then
    new.deleted_at := parent_deleted;
  end if;
  return new;
end;
$$;

create trigger recurrence_series_child before insert on public.recurrence_series for each row execute function public.tg_child_insert();
create trigger tasks_child             before insert on public.tasks             for each row execute function public.tg_child_insert();
create trigger subtasks_child          before insert on public.subtasks          for each row execute function public.tg_child_insert();
create trigger task_labels_child       before insert on public.task_labels       for each row execute function public.tg_child_insert();

-- ----------------------------------------------------------------------------
-- Row Level Security
--
-- Every table is private to its owner. The anon role has no access at all.
-- The authenticated role may select/insert/update only rows it owns. Hard
-- DELETE is not granted on data tables: the application uses tombstones, and
-- real deletion only happens through the auth.users foreign-key cascade.
-- ----------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array[
    'groups', 'labels', 'recurrence_series', 'tasks', 'subtasks',
    'task_labels', 'user_settings', 'applied_mutations'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('alter table public.%I force row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated', t);
    execute format('grant select, insert, update on table public.%I to authenticated', t);
    execute format(
      'create policy %I on public.%I for select to authenticated using (user_id = (select auth.uid()))',
      t || '_select_own', t);
    execute format(
      'create policy %I on public.%I for insert to authenticated with check (user_id = (select auth.uid()))',
      t || '_insert_own', t);
    execute format(
      'create policy %I on public.%I for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))',
      t || '_update_own', t);
    execute format(
      'create policy %I on public.%I for delete to authenticated using (user_id = (select auth.uid()))',
      t || '_delete_own', t);
  end loop;
end;
$$;

-- The idempotency ledger is pruned by its owner, so it alone allows DELETE.
grant delete on table public.applied_mutations to authenticated;

revoke execute on all functions in schema public from public, anon;
